function computeLayout(sw, sh, gap, m, pw, ph) {
  const aw = pw - 2 * m, ah = ph - 2 * m, E = 1e-9;
  const ok = sw > 0 && sh > 0;
  const cols = ok && aw >= sw - E ? Math.floor((aw + gap) / (sw + gap) + E) : 0;
  const rows = ok && ah >= sh - E ? Math.floor((ah + gap) / (sh + gap) + E) : 0;
  const usedW = cols ? cols * sw + (cols - 1) * gap : 0;
  const usedH = rows ? rows * sh + (rows - 1) * gap : 0;
  return {pw, ph, sw, sh, gap, m, aw, ah, cols, rows, count: cols * rows,
          usedW, usedH, leftW: aw - usedW, leftH: ah - usedH};
}

