function computeFill(r, fw, fh) {
  const out = {items: [], count: 0, fw, fh};
  if (!(r.count > 0 && fw > 0 && fh > 0)) return out;
  const g = r.gap, m = r.m, E = 1e-9;
  const grid = (x0, y0, W, H) => {
    let best = {n: 0, items: []};
    [[fw, fh], [fh, fw]].forEach(([w, h]) => {
      if (W < w - E || H < h - E) return;
      const c = Math.floor((W + g) / (w + g) + E), rr = Math.floor((H + g) / (h + g) + E), items = [];
      for (let i = 0; i < c; i++) for (let j = 0; j < rr; j++) items.push({x: x0 + i * (w + g), y: y0 + j * (h + g), w, h});
      if (items.length > best.n) best = {n: items.length, items};
    });
    return best.items;
  };
  const rx = m + r.usedW + g, ry = m + r.usedH + g, rw = r.aw - r.usedW - g, bh = r.ah - r.usedH - g;
  const A = grid(rx, m, rw, r.ah).concat(grid(m, ry, r.usedW, bh));
  const B = grid(rx, m, rw, r.usedH).concat(grid(m, ry, r.aw, bh));
  out.items = B.length > A.length ? B : A; out.count = out.items.length;
  return out;
}

function bahtText(value) {
  const n = Math.round((value + Number.EPSILON) * 100) / 100;
  if (!isFinite(n) || n <= 0) return 'ศูนย์บาทถ้วน';
  const D = ['ศูนย์','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'];
  const P = ['','สิบ','ร้อย','พัน','หมื่น','แสน'];
  function read(s) {
    if (s.length > 6) {
      const hi = s.slice(0, -6), lo = s.slice(-6);
      return read(hi) + 'ล้าน' + (+lo ? read(lo) : '');
    }
    let out = ''; const L = s.length;
    for (let i = 0; i < L; i++) {
      const d = +s[i], p = L - i - 1;
      if (!d) continue;
      if (p === 1) out += (d === 1 ? '' : d === 2 ? 'ยี่' : D[d]) + 'สิบ';
      else if (p === 0) out += (d === 1 && L > 1 ? 'เอ็ด' : D[d]);
      else out += D[d] + P[p];
    }
    return out;
  }
  const baht = Math.floor(n);
  const sat = Math.round((n - baht) * 100);
  let out = '';
  if (baht > 0) out += read(String(baht)) + 'บาท';
  out += sat ? read(String(sat)) + 'สตางค์' : 'ถ้วน';
  return out;
}
