    $('bibAmount').textContent = fresh.length === 1 ? 'เงินเข้า ' + money(num(last.amount)) + ' บาท' : 'เงินเข้าใหม่ ' + fresh.length + ' รายการ · ' + money(total) + ' บาท';
    $('bibMeta').textContent = (fresh.length > 1 ? 'ล่าสุด ' : '') + 'บัญชี' + (last.account || '-') + ' · ' + bankInWhen(last, true);
