        const r = await fetch(LINE_OA_URL + '/pushkey', {headers: {'x-app-key': LINE_OA_KEY}}); const j = await r.json();
        if (!j.ok || !j.key) throw new Error('ยังไม่ได้ตั้งค่า VAPID ใน worker line-oa');
