    document.querySelectorAll('[data-push-enable]').forEach(b => { b.hidden = !showBtn; });
    document.querySelectorAll('[data-push-test]').forEach(b => { b.hidden = !pushOn; });
    const st = pushOn ? '✅ เครื่องนี้เปิดแจ้งเตือนเด้งแล้ว'
      : !pushSupported() ? (isIOS && !isStandalone() ? 'iPhone: เพิ่มแอปลงหน้าจอโฮม แล้วเปิดจากไอคอนก่อน' : 'เครื่อง/เบราว์เซอร์นี้ไม่รองรับแจ้งเตือนเด้ง (iPhone ต้อง iOS 16.4 ขึ้นไป)')
      : denied ? '⚠ เครื่องนี้ปิดการแจ้งเตือนของแอปไว้ — ไปที่ การตั้งค่า → การแจ้งเตือน → Ball Sticker → เปิด "อนุญาตการแจ้งเตือน" แล้วกดปุ่มอีกครั้ง'
      : pushErr ? '⚠ เปิดไม่สำเร็จ: ' + pushErr : '';
    document.querySelectorAll('[data-push-status]').forEach(el => { el.textContent = st; el.classList.toggle('err', !pushOn && !!(denied || pushErr)); });
