      'ราคารวม VAT: ' + money(r.total) + ' บาท';
    navigator.clipboard.writeText(text).then(() => toast('คัดลอกผลลัพธ์แล้ว')).catch(() => toast('คัดลอกอัตโนมัติไม่ได้'));
