  function totals() {
    const sub = round2(items.reduce((a, i) => a + num(i.qty) * num(i.price), 0));
    const disc = Math.min(Math.max(0, num($('discount').value)), sub);
    const base = round2(sub - disc);
    const mode = $('vatMode').value, rate = Math.max(0, num($('vatRate').value));
    let vat = 0, before = base, total = base;
    if (mode === 'add') { vat = round2(base * rate / 100); total = round2(base + vat); }
    else if (mode === 'incl') { vat = round2(base * rate / (100 + rate)); before = round2(base - vat); }
    // vd = ตัวหารถอด VAT ออกจากราคาเต็ม ใช้ตอนแสดงราคาต่อชิ้น/รวมรายการในตารางสำหรับโหมด "รวม VAT ในราคา"
    // เพื่อให้ตัวเลขในตารางรายการเป็นราคาก่อน VAT ที่สอดคล้องกับยอดรวมด้านล่าง ส่วน "รวมทั้งสิ้น" ยังคงเป็นราคาเต็มตามยอดจริงเสมอ
    const vd = (mode === 'incl' && rate > 0) ? (1 + rate / 100) : 1;
    const dep = Math.max(0, num($('deposit').value));
    return {sub, disc, base, mode, rate, vat, before, total, dep, vd, bal: Math.max(0, round2(total - dep))};
  }

