  function fitFrame(frameId, sheetId) {
    const frame = $(frameId), sheet = $(sheetId);
    if (!frame || !sheet) return;
    const w = frame.clientWidth, bw = sheet.offsetWidth;
    if (!w || !bw) return;
    const k = Math.min(1, w / bw);
    sheet.style.transform = k < 1 ? 'scale(' + k + ')' : '';
    frame.style.height = Math.ceil(sheet.offsetHeight * k) + 'px';
  }
  function fitBill() { fitFrame('a4frame', 'bill'); }

  function nextNo() {
    // รูปแบบเลขที่เอกสาร: BS + ปี พ.ศ. 2 หลักท้าย + เดือน 2 หลัก + เลขรันต่อเนื่อง 4 หลัก เช่น BS69090001
    // (BS = Ball Sticker, 69 = พ.ศ. 2569, 09 = เดือนกันยายน, 0001 = เลขที่ลำดับในเดือนนั้น)
    // ช่องนี้แก้ไขเองได้เสมอ ตัวเลขที่ระบบเติมให้เป็นแค่คำแนะนำเริ่มต้น
    const dateVal = $('billDate').value || todayISO();
    const parts = dateVal.split('-'); // [ค.ศ., เดือน, วัน]
    const beYY = String((+parts[0] + 543) % 100).padStart(2, '0');
    const mm = parts[1] || '01';
    const prefix = 'BS' + beYY + mm;
    const n = store.get('bs_bills', []).filter(b => String(b.no).indexOf(prefix) === 0).length + 1;
    return prefix + String(n).padStart(4, '0');
  }

