    sel.innerHTML = '<option value="">— เลือกเดือน —</option>' +
      months.map(m => '<option value="' + esc(m) + '">' + esc(thMonthFull(m)) + ' (' + list.filter(b => monthKey(b.date) === m).length + ' ใบ)</option>').join('');
