  function quoteTotals() {
    const sub = round2(quoteItems.reduce((a, i) => a + num(i.qty) * num(i.price), 0));
    const disc = Math.min(Math.max(0, num($('quoteDiscount').value)), sub);
    const base = round2(sub - disc);
    const mode = $('quoteVatMode').value, rate = Math.max(0, num($('quoteVatRate').value));
    let vat = 0, before = base, total = base;
    if (mode === 'add') { vat = round2(base * rate / 100); total = round2(base + vat); }
    else if (mode === 'incl') { vat = round2(base * rate / (100 + rate)); before = round2(base - vat); }
    const vd = (mode === 'incl' && rate > 0) ? (1 + rate / 100) : 1;
    return {sub, disc, base, mode, rate, vat, before, total, vd};
  }
  // คำนวณยอดจากเรคคอร์ดที่บันทึกไว้แล้ว (ใช้แสดงในประวัติ) — แยกต่างหากจาก billCalc() โดยสิ้นเชิง ไม่เกี่ยวกับ bs_bills
  function quoteCalc(qrec) {
    const its = qrec.items || [];
    const sub = round2(its.reduce((a, i) => a + num(i.qty) * num(i.price), 0));
    const disc = Math.min(Math.max(0, num(qrec.discount)), sub);
    const base = round2(sub - disc);
    const mode = qrec.vatMode || 'add', rate = Math.max(0, num(qrec.vatRate));
    let vat = 0, total = base;
    if (mode === 'add') { vat = round2(base * rate / 100); total = round2(base + vat); }
    else if (mode === 'incl') { vat = round2(base * rate / (100 + rate)); }
    return {sub, disc, base, vat, total};
  }

