    let gen = [1]; for (let i = 0; i < ecn; i++) { const ng = new Array(gen.length + 1).fill(0); gen.forEach((g, j) => { ng[j] ^= g; ng[j + 1] ^= mul(g, EXP[i]); }); gen = ng; }
