    al.forEach(r => al.forEach(c => { if ((r === 6 && c === 6) || (r === 6 && c === la) || (r === la && c === 6)) return; for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) set(r + i, c + j, Math.max(Math.abs(i), Math.abs(j)) !== 1); }));
