  // ซ่อน 2 ตัวท้ายของเลขพัสดุในรายการ (กดปุ่มเพื่อดูเต็ม)
  const revealedTrack = new Set();
  function maskTrackCode(c) { c = String(c || ''); return c.length > 2 ? c.slice(0, -2) + '••' : c; }
  function renderTrackingHistory() {
    // เรียงตามลำดับของ iship เอง (วันที่สร้างออเดอร์จริง) ถ้ามีข้อมูล ไม่งั้นใช้เวลาที่บันทึกในเครื่องแทน
    const sortKey = t => (t.ishipCreatedAt != null ? t.ishipCreatedAt : (t.savedAt || 0));
    const list = store.get('bs_tracking', []).slice().sort((a, b) => sortKey(b) - sortKey(a));
    const q = $('trackHistSearch') ? $('trackHistSearch').value.trim() : '';
    // อัปเดตตัวเลือกใน dropdown "ผู้ส่ง/เพจ" ให้ตรงกับรายชื่อผู้ส่งที่มีอยู่จริงในประวัติ (เผื่อร้านมีหลายเพจ/หลายที่อยู่ต้นทาง)
    const senderSel = $('trackSenderFilter');
    let senderFilter = '';
    if (senderSel) {
      senderFilter = senderSel.value;
      const senders = Array.from(new Set(list.map(t => t.sender).filter(Boolean))).sort();
      const optsHtml = '<option value="">ทั้งหมด</option>' + senders.map(s => '<option value="' + esc(s) + '"' + (s === senderFilter ? ' selected' : '') + '>' + esc(s) + '</option>').join('');
      if (senderSel.innerHTML !== optsHtml) senderSel.innerHTML = optsHtml;
      if (senderFilter && senders.indexOf(senderFilter) < 0) senderFilter = ''; // ผู้ส่งที่เลือกไว้ไม่มีในรายการแล้ว (เช่นลบรายการนั้นหมด) กลับเป็น "ทั้งหมด"
    }
    let shown = q ? list.filter(t => matchesSearch(t.code, q) || matchesSearch(t.carrier, q) || matchesSearch(t.customer, q) || matchesSearch(t.sender, q) || matchesSearch(t.senderAddress, q)) : list;
    if (senderFilter) shown = shown.filter(t => t.sender === senderFilter);
    $('trackHistCount').textContent = list.length;
    if (!list.length) { $('trackHistory').innerHTML = '<p class="empty">ยังไม่มีประวัติ สร้างข้อความแรกได้เลย</p>'; return; }
    if (!shown.length) { $('trackHistory').innerHTML = '<p class="empty">ไม่พบรายการที่ค้นหา</p>'; return; }
    let ishipSyncWhen = '';
    try { const at = +localStorage.getItem(ISHIP_SYNC_KEY) || 0; if (at) ishipSyncWhen = bankInWhen({createdAt: at}, true); } catch (e) {}
    $('trackHistory').innerHTML = '<ul>' + shown.map(t => {
      const st = t.status || 'transit';
      const cls = (TRACK_STATUS[st] || TRACK_STATUS.transit).cls;
      const live = cloudDb ? liveTrackCache[t.code] : undefined;
      let liveHtml = '';
      if (live && live.data) {
        const d = describeLiveTracking(live.data);
        liveHtml = '<div class="live-status live-ok"><span class="live-dot live-dot-on"></span>LIVE จาก iship: ' + esc(d.statusText) + (d.timeText ? ' · ' + esc(d.timeText) : '') + '</div>';
      } else if (t.ishipStatusName) {
        // สถานะจากรายการออเดอร์ของ iship (เช็กให้เองทุก 10 นาที หรือกด "เช็กสถานะล่าสุด")
        const doneCls = st === 'delivered' ? ' live-ok' : st === 'issue' ? ' live-bad' : ' live-none';
        liveHtml = '<div class="live-status' + doneCls + '"><span class="live-dot' + (st === 'delivered' ? ' live-dot-on' : '') + '"></span>iship: <b>' + esc(translateIshipStatus(t.ishipStatusName)) + '</b>' +
          (ishipSyncWhen ? '<span class="live-when">เช็กล่าสุด ' + esc(ishipSyncWhen) + '</span>' : '') + '</div>';
      } else if (cloudDb) {
        if (!trackLiveOn) {
          liveHtml = '<div class="live-status live-none">ยังไม่มีสถานะจาก iship — กด “เช็กสถานะล่าสุดจาก iship” ด้านบน</div>';
        } else if (!live) {
          liveHtml = '<div class="live-status live-pending">⏳ กำลังเช็กสถานะจาก iship...</div>';
        } else if (!live.data) {
          liveHtml = '<div class="live-status live-none"><span class="live-dot"></span>ยังไม่มีสถานะจาก iship สำหรับเลขนี้ (เลขที่ไม่ได้สร้างผ่าน iship จะไม่มีสถานะ)</div>';
        } else {
          const d = describeLiveTracking(live.data);
          liveHtml = '<div class="live-status live-ok"><span class="live-dot live-dot-on"></span>LIVE จาก iship: ' + esc(d.statusText) + (d.timeText ? ' · ' + esc(d.timeText) : '') + '</div>';
        }
      }
      const senderHtml = t.sender ? '<div class="sender-info">📍 ผู้ส่ง: <b>' + esc(t.sender) + '</b>' + '</div>' : '';
      return '<li data-id="' + esc(t.id) + '"><div class="meta"><b>' + esc(revealedTrack.has(t.id) ? t.code : maskTrackCode(t.code)) + '</b>' + (t.customer ? '<span class="rcpt">' + esc(t.customer) + '</span>' : '') + '<small>' + esc(t.carrier) + ' · ' + esc(new Date(t.savedAt).toLocaleString('th-TH')) + '</small></div>' + senderHtml +
      '<select class="track-status-select status-pill ' + cls + '" data-id="' + esc(t.id) + '" aria-label="สถานะพัสดุ">' +
        Object.keys(TRACK_STATUS).map(k => '<option value="' + k + '"' + (k === st ? ' selected' : '') + '>' + TRACK_STATUS[k].label + '</option>').join('') +
      '</select>' +
      (trackingLink(t.carrier, t.code) ? '<button class="btn small primary" data-act="checklive" type="button">🔍 เปิดหน้าติดตาม</button>' : '') +
      '<button class="btn small" data-act="reveal" type="button">' + (revealedTrack.has(t.id) ? '🙈 ซ่อนเลข' : '👁 ดูเลขเต็ม') + '</button>' +
      '<button class="btn small" data-act="copy" type="button">คัดลอก</button>' +
      '<button class="btn small edit" data-act="use" type="button">เปิดดู</button>' +
      '<button class="btn small del" data-act="del" type="button">ลบ</button>' +
      liveHtml + '</li>';
    }).join('') + '</ul>';
    if (cloudDb && trackLiveOn) {
      shown.forEach(t => subscribeLiveTracking(t.code)); // เปิดฟังสถานะแบบเรียลไทม์ไว้ทุกรายการที่แสดงอยู่
    }
  }
  $('trackHistory').addEventListener('click', e => {
    const refreshBtn = e.target.closest('button[data-refresh]');
    if (refreshBtn) {
      const code = refreshBtn.dataset.refresh;
      fetchLiveTracking(code, true).then(() => renderTrackingHistory());
      return;
    }
    const btn = e.target.closest('button[data-act]'); if (!btn) return;
    const li = btn.closest('li'); const id = li.dataset.id;
    if (btn.dataset.act === 'reveal') { revealedTrack.has(id) ? revealedTrack.delete(id) : revealedTrack.add(id); renderTrackingHistory(); return; }
    const list = store.get('bs_tracking', []);
    const rec = list.find(t => t.id === id); if (!rec) return;
    if (btn.dataset.act === 'checklive') {
      const link = trackingLink(rec.carrier, rec.code);
      if (link) window.open(link, '_blank', 'noopener');
    } else if (btn.dataset.act === 'copy') {
      navigator.clipboard.writeText(rec.message).then(() => toast('คัดลอกข้อความแล้ว')).catch(() => toast('คัดลอกอัตโนมัติไม่ได้'));
    } else if (btn.dataset.act === 'use') {
      $('trackCode').value = rec.code; $('trackCarrier').value = rec.carrier; $('trackCustomer').value = rec.customer || '';
      $('trackMessage').value = rec.message;
      toast('เปิดข้อความนี้แล้ว');
    } else if (btn.dataset.act === 'del') {
      if (trackDelArmed !== id) {
        trackDelArmed = id; btn.textContent = 'กดอีกครั้งเพื่อลบ'; btn.classList.add('confirm');
        clearTimeout(trackDelTimer); trackDelTimer = setTimeout(() => { trackDelArmed = null; renderTrackingHistory(); }, 4000);
        return;
      }
      clearTimeout(trackDelTimer); trackDelArmed = null;
      unsubscribeLiveTracking(rec.code);
      store.set('bs_tracking', list.filter(t => t.id !== id));
      cloudDelete('tracking', id);
      renderTrackingHistory();
      toast('ลบรายการแล้ว');
    }
  });
  $('trackHistory').addEventListener('change', e => {
    const sel = e.target.closest('select.track-status-select'); if (!sel) return;
    updateTrackingStatus(sel.dataset.id, sel.value);
  });
  $('trackHistSearch').addEventListener('input', renderTrackingHistory);
  $('trackSenderFilter').addEventListener('change', renderTrackingHistory);
  $('track-make').addEventListener('click', saveTracking);
  $('track-new').addEventListener('click', newTracking);
  $('track-copy').addEventListener('click', copyTrackingMessage);
  $('track-import-iship').addEventListener('click', () => importOrdersFromIship(30));
  $('track-live-toggle').addEventListener('click', () => {
    trackLiveOn = !trackLiveOn;
    try { localStorage.setItem(TRACK_LIVE_KEY, trackLiveOn ? '1' : '0'); } catch (e) {}
    if (!trackLiveOn) store.get('bs_tracking', []).forEach(t => unsubscribeLiveTracking(t.code));
    paintTrackLiveBtn();
    updateLiveTimer();
    renderTrackingHistory();
  });
  paintTrackLiveBtn();
  updateLiveTimer();
  setTimeout(refreshAllLive, 3000); // ดึงสถานะรอบแรกหลังเปิดแอปไม่นาน
  // สรุปวันนี้: นับรายการที่บันทึกหรือสร้างในวันนี้ (ตามเวลาเครื่อง) และแสดงชื่อลูกค้า
  function dayKey(ms) {
    const d = new Date(ms); if (isNaN(d)) return '';
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  $('track-day-summary').addEventListener('click', () => {
    const box = $('trackDaySummary');
    if (!box.hidden) { box.hidden = true; $('track-day-summary').setAttribute('aria-expanded', 'false'); return; }
    const today = dayKey(Date.now());
    const list = store.get('bs_tracking', []).filter(t => dayKey(t.ishipCreatedAt != null ? t.ishipCreatedAt : t.savedAt) === today);
    box.innerHTML = '<div class="track-day-head">วันนี้ส่ง <b>' + list.length + '</b> กล่อง</div>' +
      (list.length
        ? '<ul>' + list.map(t => '<li><b>' + esc((t.customer || '').trim() || 'ไม่ระบุชื่อ') + '</b><small>' + esc(t.carrier || '') + ' · ' + esc(t.code || '') + '</small></li>').join('') + '</ul>'
        : '<p class="empty">ยังไม่มีรายการของวันนี้</p>');
    box.hidden = false;
    $('track-day-summary').setAttribute('aria-expanded', 'true');
  });
  $('track-refresh-live').addEventListener('click', () => {
    syncIshipStatuses(true);
    if (cloudDb) Promise.all(store.get('bs_tracking', []).map(t => fetchLiveTracking(t.code, true))).then(() => renderTrackingHistory());
  });
  $('track-clear-all').addEventListener('click', () => {
    const btn = $('track-clear-all');
    if (!trackClearArmed) {
      trackClearArmed = true; btn.textContent = 'กดอีกครั้งเพื่อล้างทั้งหมด';
      clearTimeout(trackClearTimer); trackClearTimer = setTimeout(() => { trackClearArmed = false; btn.textContent = 'ล้างทั้งหมด'; }, 4000);
      return;
    }
    clearTimeout(trackClearTimer); trackClearArmed = false; btn.textContent = 'ล้างทั้งหมด';
    store.get('bs_tracking', []).forEach(t => { unsubscribeLiveTracking(t.code); cloudDelete('tracking', t.id); });
    store.set('bs_tracking', []);
    renderTrackingHistory();
    toast('ล้างประวัติทั้งหมดแล้ว');
  });

  /* ---------------- ใบคอนเฟิร์มงาน (ใบสั่งผลิตภายในร้าน ไม่มีราคา) ---------------- */
  let jobItems = [{name: '', qty: 1, note: ''}];
  let currentJobId = null;
  let jobPhotos = [];
  let jobStatus = 'pending';
  const JOB_STATUS_LABEL = {pending: 'รอทำ', printed: 'ผลิตแล้ว', shipped: 'จัดส่ง'};
  function renderJobStatusBadge() {
    const el = $('jobStatusBadge'); if (!el) return;
    el.className = 'status-pill ' + jobStatus;
    el.textContent = JOB_STATUS_LABEL[jobStatus] || JOB_STATUS_LABEL.pending;
  }
  function markJobPrinted() {
    if (jobStatus !== 'pending') return;
    jobStatus = 'printed';
    renderJobStatusBadge();
    if (currentJobId) updateJobStatus(currentJobId, 'printed', {silent: true});
  }
  function updateJobStatus(id, status, opts) {
    opts = opts || {};
    const list = store.get('bs_jobs', []);
    const idx = list.findIndex(j => j.id === id);
    if (idx < 0) return;
    list[idx].status = status;
    store.set('bs_jobs', list);
    cloudSave('jobs', list[idx]);
    if (currentJobId === id) { jobStatus = status; renderJobStatusBadge(); }
    renderJobHistory();
    if (!opts.silent) toast('อัปเดตสถานะเป็น "' + (JOB_STATUS_LABEL[status] || status) + '" แล้ว');
  }

  function readJobPhotos(files) {
    Array.from(files || []).forEach(file => {
      if (!file || !/^image\//.test(file.type)) return;
      const reader = new FileReader();
      reader.onload = () => {
        const img = new Image();
        img.onload = () => {
          const maxDim = 1000;
          let w = img.width, h = img.height;
          if (w > maxDim || h > maxDim) { const k = maxDim / Math.max(w, h); w = Math.round(w * k); h = Math.round(h * k); }
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          jobPhotos.push(canvas.toDataURL('image/jpeg', 0.75));
          renderJobPhotos(); renderJob();
        };
        img.src = reader.result;
      };
      reader.readAsDataURL(file);
    });
  }
  function renderJobPhotos() {
    const wrap = $('jobPhotoWrap');
    if (!jobPhotos.length) { wrap.hidden = true; wrap.innerHTML = ''; return; }
    wrap.hidden = false;
    wrap.innerHTML = jobPhotos.map((src, i) =>
      '<div class="job-photo-item"><img src="' + src + '" alt="รูปอ้างอิงงาน ' + (i + 1) + '">' +
      '<button type="button" data-i="' + i + '" aria-label="ลบรูปนี้">✕</button></div>').join('');
  }

  function renderJobItems() {
    $('jobItems').innerHTML = jobItems.map((it, i) =>
      '<div class="item job" data-i="' + i + '">' +
      '<input class="txt i-name" type="text" placeholder="ชื่องาน / สเปก" aria-label="ชื่องาน" value="' + esc(it.name) + '">' +
      '<input class="num i-qty" type="number" inputmode="decimal" step="any" min="0" placeholder="จำนวน" aria-label="จำนวน" value="' + esc(it.qty) + '">' +
      '<input class="txt i-note" type="text" placeholder="หมายเหตุ" aria-label="หมายเหตุ" value="' + esc(it.note || '') + '">' +
      '<button class="del" type="button" aria-label="ลบรายการ">✕</button></div>').join('');
  }

  function renderJob() {
    renderJobHTML();
    fitJob();
  }

  // คำนวณขนาด/จำนวนคอลัมน์ของรูปอ้างอิงงานให้เหมาะกับจำนวนรูป (รูปน้อย = ใหญ่, รูปเยอะ = จัดกริดถี่ขึ้น)
  // ใช้ร่วมกันทั้งตัวอย่าง HTML (มิลลิเมตร) และ PDF (มิลลิเมตรเช่นกัน ตรงกับสเกล S ของ canvas)
  function photoGridLayout(n) {
    const CWmm = 186, GAP = 6;
    let cols = n <= 1 ? 1 : n <= 4 ? 2 : n <= 9 ? 3 : 4;
    let size = (CWmm - (cols - 1) * GAP) / cols;
    if (cols === 1) size = Math.min(size, 130);
    return {cols, size, gap: GAP};
  }
  function renderJobHTML() {
    const dash = v => v && String(v).trim() ? esc(v) : '—';
    const shown = jobItems.filter(i => i.name.trim());
    const rows = shown.length ? shown.map((i, n) =>
      '<tr><td class="n">' + (n + 1) + '</td><td>' + esc(i.name) + (i.note && i.note.trim() ? '<div style="color:#4a5a72;font-size:12px;margin-top:2px">' + esc(i.note) + '</div>' : '') + '</td><td class="r">' + esc(fmt(num(i.qty))) + '</td></tr>').join('')
      : '<tr><td class="n">—</td><td colspan="2" style="color:#4a5a72">ยังไม่มีรายการ</td></tr>';
    $('jobSheet').innerHTML =
      '<header class="sh-head"><div class="sh-brand">' + logoImg() + '<div><div class="sh-name">' + esc(shop.name) + '</div><div class="sh-lines">' + shopLines() + '</div></div></div>' +
      '<div class="sh-doc"><h2>ใบคอนเฟิร์มงาน</h2><div class="sh-lines">เลขที่ <b>' + esc($('jobNo').value) + '</b><br>วันที่สั่ง ' + esc(thDate($('jobDate').value)) +
      '<br>กำหนดส่ง ' + ($('jobDue').value ? esc(thDate($('jobDue').value)) : '—') + '</div></div></header>' +
      '<section class="cust"><h3>ลูกค้า</h3><div><b>' + dash($('jName').value) + '</b></div><div>' + dash($('jPhone').value) + '</div>' +
      ($('jAddr').value.trim() ? '<div>' + esc($('jAddr').value.trim()) + '</div>' : '') + '</section>' +
      '<div class="tbl-wrap"><table class="lines"><thead><tr><th class="n">ลำดับ</th><th>รายการงาน / สเปก</th><th class="r">จำนวน</th></tr></thead><tbody>' + rows + '</tbody></table></div>' +
      ($('jobNote').value.trim() ? '<div class="note"><b>ข้อกำหนดการผลิต / หมายเหตุ</b><br>' + esc($('jobNote').value) + '</div>' : '') +
      (jobPhotos.length ? (() => {
        const gl = photoGridLayout(jobPhotos.length);
        return '<div class="note"><b>รูปอ้างอิงงาน</b><div class="job-photo-grid">' +
          jobPhotos.map((src, i) => '<img src="' + src + '" alt="รูปอ้างอิงงาน ' + (i + 1) + '" style="width:' + gl.size + 'mm;height:' + gl.size + 'mm">').join('') + '</div></div>';
      })() : '') +
      '<div class="sign"><div>ลูกค้าตรวจสอบและยืนยันงาน ____________________</div><div>ผู้รับงาน ____________________</div></div>';
  }

  function fitJob() {
    const frame = $('jobA4frame'), sheet = $('jobSheet');
    const w = frame.clientWidth, bw = sheet.offsetWidth;
    if (!w || !bw) return;
    const k = Math.min(1, w / bw);
    sheet.style.transform = k < 1 ? 'scale(' + k + ')' : '';
    frame.style.height = Math.ceil(sheet.offsetHeight * k) + 'px';
  }

  function nextJobNo() {
    const d = ($('jobDate').value || todayISO()).replace(/-/g, '').slice(2);
    const prefix = 'JB' + d;
    const n = store.get('bs_jobs', []).filter(j => String(j.no).indexOf(prefix) === 0).length + 1;
    return prefix + '-' + String(n).padStart(3, '0');
  }

  function collectJob() {
    return {no: $('jobNo').value, date: $('jobDate').value, due: $('jobDue').value, account: $('jobAccount').value, page: $('jobPage').value, bankInIds: jobBankInIds.slice(), bankInId: jobBankInIds[0] || '', slipAmount: $('jobSlipAmount').value, jName: $('jName').value, jPhone: $('jPhone').value, jAddr: $('jAddr').value,
      items: jobItems.map(i => ({name: i.name, qty: i.qty, note: i.note})), note: $('jobNote').value, photos: jobPhotos.slice(), status: jobStatus};
  }
  function applyJob(j) {
    $('jobNo').value = j.no || ''; $('jobDate').value = j.date || todayISO(); $('jobDue').value = j.due || '';
    $('jobAccount').value = j.account || ''; $('jobSlipAmount').value = j.slipAmount || '';
    $('jobPage').value = PAGE_LABEL[j.page] ? j.page : 'ball';
    jobBankInIds = jobBankIdsOf(j); if ($('jobBankInList')) { $('jobBankInList').hidden = true; $('jobBankInBtn').setAttribute('aria-expanded', 'false'); }
    $('jName').value = j.jName || ''; $('jPhone').value = j.jPhone || ''; $('jAddr').value = j.jAddr || '';
    jobItems = (j.items && j.items.length) ? j.items.map(i => ({name: i.name || '', qty: i.qty, note: i.note || ''})) : [{name: '', qty: 1, note: ''}];
    $('jobNote').value = j.note || '';
    jobPhotos = (j.photos && j.photos.length) ? j.photos.slice() : [];
    jobStatus = j.status || 'pending';
    renderJobItems(); renderJobPhotos(); renderJobStatusBadge(); renderJob();
  }
  function renderJobEditState() {
    const el = $('jobEditState');
    if (currentJobId) { el.textContent = 'กำลังแก้ไขใบที่บันทึกไว้ กด “บันทึกลงประวัติ” เพื่อบันทึกทับฉบับเดิม'; el.classList.add('editing'); }
    else { el.textContent = 'ใบใหม่ ยังไม่ได้บันทึกลงประวัติ'; el.classList.remove('editing'); }
  }
  function newJob() {
    currentJobId = null;
    applyJob({date: todayISO()});
    $('jobNo').value = nextJobNo();
    renderJob();
    renderJobEditState();
  }
  function renderJobHistory() {
    const list = store.get('bs_jobs', []).slice().sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
    const notice = cloudNotice() || (storageOK ? '' : '<p class="notice">เบราว์เซอร์นี้ไม่อนุญาตให้เก็บข้อมูลถาวร ประวัติจะอยู่จนกว่าจะปิดหน้านี้ ควรดาวน์โหลด PDF เก็บไว้ทุกครั้ง</p>');
    if (!list.length) { $('jobHistory').innerHTML = notice + '<p class="empty">ยังไม่มีใบคอนเฟิร์มงานที่บันทึก กด “บันทึกลงประวัติ” เพื่อเก็บไว้เปิดแก้ไขภายหลัง</p>'; return; }
    const q = $('jobHistSearch') ? $('jobHistSearch').value : '';
    const shown = list.filter(j => matchesSearch(j.jName, q));
    if (!shown.length) { $('jobHistory').innerHTML = notice + '<p class="empty">ไม่พบใบคอนเฟิร์มงานของลูกค้าชื่อ “' + esc(q) + '”</p>'; return; }
    $('jobHistory').innerHTML = notice + '<ul>' + shown.map(j => {
      const st = j.status || 'pending';
      return '<li data-id="' + esc(j.id) + '">' + ((j.photos && j.photos[0]) ? '<img class="thumb" src="' + j.photos[0] + '" alt="">' : '') +
      '<div class="meta"><b>' + esc(j.no) + '</b><small>' + esc(thDate(j.date)) + ' · ' + esc(j.jName || 'ไม่ระบุชื่อลูกค้า') + (PAGE_LABEL[j.page] ? ' · ' + esc(PAGE_LABEL[j.page]) : '') + (j.account ? ' · บัญชี ' + esc(j.account) : '') + (num(j.slipAmount) > 0 ? ' · สลิป ' + money(num(j.slipAmount)) + ' บาท' : '') + (j.createdBy ? ' · โดย ' + esc(j.createdBy) : '') + (j.photos && j.photos.length ? ' · แนบรูป ' + j.photos.length + ' รูป' : '') + '</small></div>' +
      '<select class="job-status-select status-pill ' + st + '" data-id="' + esc(j.id) + '" aria-label="สถานะงาน">' +
        Object.keys(JOB_STATUS_LABEL).map(k => '<option value="' + k + '"' + (k === st ? ' selected' : '') + '>' + JOB_STATUS_LABEL[k] + '</option>').join('') +
      '</select>' +
      '<span class="amt">' + (j.items || []).filter(i => (i.name || '').trim()).length + ' รายการ</span>' +
      '<button class="btn small edit" data-act="open" type="button">เปิดแก้ไข</button>' +
      '<button class="btn small del" data-act="del" type="button">ลบ</button></li>';
    }).join('') + '</ul>';
  }
  function saveJob() {
    const list = store.get('bs_jobs', []);
    const data = collectJob();
    if (!String(data.no).trim()) { toast('ใส่เลขที่ใบก่อนบันทึก'); $('jobNo').focus(); return; }
    const id = currentJobId || ('j' + Date.now());
    const idx = list.findIndex(j => j.id === id);
    const createdBy = idx >= 0 ? list[idx].createdBy : (currentUser ? currentUser.name : '');
    const prevBankInIds = idx >= 0 ? jobBankIdsOf(list[idx]) : [];
    const rec = Object.assign({id, savedAt: Date.now(), createdBy}, data);
    if (idx >= 0) list[idx] = rec; else list.push(rec);
    const wasEditing = idx >= 0;
    currentJobId = rec.id;
    const persisted = store.set('bs_jobs', list);
    cloudSave('jobs', rec);
    linkBankIn(rec, prevBankInIds);
    upsertCustomer(rec.jName, rec.jPhone, rec.jAddr);
    renderJobHistory(); renderJobEditState();
    syncRecordPhotosToCloud('bs_jobs', 'jobs', rec.id, 'photos', renderJobHistory);
    toast((persisted || cloudStatus === 'on') ? (wasEditing ? 'บันทึกทับใบ ' : 'บันทึกใบ ') + rec.no + ' แล้ว'
                    : 'บันทึกชั่วคราวแล้ว (เบราว์เซอร์เครื่องนี้ไม่อนุญาตให้เก็บถาวร และยังต่อคลาวด์ไม่ได้ — อย่าเพิ่งปิดหน้านี้)');
  }

  /* ---------------- ใบราคาส่ง (เอกสารราคาขายส่ง แยกต่างหากจากใบเสร็จ/ใบกำกับภาษีโดยสิ้นเชิง
     ไม่มี VAT ไม่รันเลขที่เอกสารอัตโนมัติ และไม่รวมกับ bs_bills / แดชบอร์ด / รายงานภาษีใดๆ ทั้งสิ้น
     เก็บข้อมูลแยกที่ localStorage key "bs_wholesale" และ Firestore collection "wholesale" ของตัวเอง) ---------------- */
  let wholesaleItems = [{name: '', qty: 1, price: 0}];
  let currentWholesaleId = null;
  let whDelArmed = null, whDelTimer = null;

  function renderWholesaleItems() {
    $('wholesaleItems').innerHTML = wholesaleItems.map((it, i) =>
      '<div class="item" data-i="' + i + '">' +
      '<input class="txt i-name" type="text" placeholder="ชื่อรายการ" aria-label="ชื่อรายการ" value="' + esc(it.name) + '">' +
      '<input class="num i-qty" type="number" inputmode="decimal" step="any" min="0" placeholder="จำนวน" aria-label="จำนวน" value="' + esc(it.qty) + '">' +
      '<input class="num i-price" type="number" inputmode="decimal" step="any" min="0" placeholder="ราคา/ชิ้น" aria-label="ราคาต่อชิ้น" value="' + esc(it.price) + '">' +
      '<output class="i-total" aria-label="รวม">' + money(num(it.qty) * num(it.price)) + '</output>' +
      '<button class="del" type="button" aria-label="ลบรายการ">✕</button></div>').join('');
  }

  // คำนวณยอดจากฟอร์มที่กำลังกรอกอยู่ตอนนี้ (ไม่มี VAT — เป็นแค่ ยอดรวม - ส่วนลด)
  function wholesaleTotals() {
    const sub = round2(wholesaleItems.reduce((a, i) => a + num(i.qty) * num(i.price), 0));
    const disc = Math.min(Math.max(0, num($('whDiscount').value)), sub);
    const total = round2(sub - disc);
    return {sub, disc, total};
  }
  // คำนวณยอดจากเรคคอร์ดที่บันทึกไว้แล้ว (ใช้แสดงในลิสต์ประวัติ) — แยกต่างหากจาก billCalc() โดยสิ้นเชิง ไม่เกี่ยวกับ bs_bills
  function wholesaleCalc(w) {
    const its = w.items || [];
    const sub = round2(its.reduce((a, i) => a + num(i.qty) * num(i.price), 0));
    const disc = Math.min(Math.max(0, num(w.discount)), sub);
    return {sub, disc, total: round2(sub - disc)};
  }

  function renderWholesale() {
    renderWholesaleHTML();
    fitWholesale();
  }

  function renderWholesaleHTML() {
    const t = wholesaleTotals();
    const shown = wholesaleItems.filter(i => i.name.trim() || num(i.qty) * num(i.price) > 0);
    const rows = shown.length ? shown.map((i, n) =>
      '<tr><td class="n">' + (n + 1) + '</td><td>' + esc(i.name) + '</td><td class="r">' + esc(fmt(num(i.qty))) +
      '</td><td class="r">' + money(num(i.price)) + '</td><td class="r">' + money(num(i.qty) * num(i.price)) + '</td></tr>').join('')
      : '<tr><td class="n">—</td><td colspan="4" style="color:#4a5a72">ยังไม่มีรายการ</td></tr>';
    const custParts = [];
    if ($('whName').value.trim()) custParts.push('<div><b>' + esc($('whName').value.trim()) + '</b></div>');
    $('wholesaleSheet').innerHTML =
      '<header class="sh-head"><div class="sh-brand">' + logoImg() + '<div><div class="sh-name">' + esc(shop.name) + '</div><div class="sh-lines">' + shopLines() + '</div></div></div>' +
      '<div class="sh-doc"><h2>ใบราคาส่ง</h2><div class="sh-lines">' + ($('whRef').value.trim() ? 'อ้างอิง <b>' + esc($('whRef').value.trim()) + '</b><br>' : '') + 'วันที่ ' + esc(thDate($('whDate').value)) + '</div></div></header>' +
      '<section class="cust"><h3>ลูกค้า / ผู้ซื้อ</h3>' + custParts.join('') + '</section>' +
      '<div class="tbl-wrap"><table class="lines"><thead><tr><th class="n">ลำดับ</th><th>รายการ</th><th class="r">จำนวน</th><th class="r">ราคา/ชิ้น</th><th class="r">รวม</th></tr></thead><tbody>' + rows + '</tbody></table></div>' +
      '<div class="totals-row"><div class="words"><b>' + bahtText(t.total) + '</b></div><div class="totals">' +
      '<div class="tot"><span>ส่วนลด</span><span>' + money(t.disc) + '</span></div>' +
      '<div class="tot strong"><span>รวมทั้งสิ้น</span><span>' + money(t.total) + '</span></div></div></div>' +
      ($('whNote').value.trim() ? '<div class="note"><b>หมายเหตุ</b> ' + esc($('whNote').value) + '</div>' : '') +
      '<div class="sign"><div class="sign-col"><div class="sign-line"></div><div class="sign-label">ผู้ออกใบราคาส่ง</div><div class="sign-date">วันที่ ' + esc(thDate($('whDate').value)) + '</div></div>' +
      '<div class="sign-col"><div class="sign-line"></div><div class="sign-label">ผู้รับใบราคาส่ง</div><div class="sign-date">วันที่ ....../....../......</div></div></div>';
  }

  function fitWholesale() { fitFrame('wholesaleA4frame', 'wholesaleSheet'); }

  function collectWholesale() {
    return {ref: $('whRef').value, date: $('whDate').value, buyerName: $('whName').value,
      items: wholesaleItems.map(i => ({name: i.name, qty: i.qty, price: i.price})),
      discount: $('whDiscount').value, note: $('whNote').value};
  }
  function applyWholesale(w) {
    $('whRef').value = w.ref || ''; $('whDate').value = w.date || todayISO();
    $('whName').value = w.buyerName || '';
    wholesaleItems = (w.items && w.items.length) ? w.items.map(i => ({name: i.name || '', qty: i.qty, price: i.price})) : [{name: '', qty: 1, price: 0}];
    $('whDiscount').value = w.discount || 0; $('whNote').value = w.note || '';
    renderWholesaleItems(); renderWholesale();
  }
  function renderWholesaleEditState() {
    const el = $('wholesaleEditState');
    if (currentWholesaleId) { el.textContent = 'กำลังแก้ไขใบราคาส่งที่บันทึกไว้ กด “บันทึกลงประวัติ” เพื่อบันทึกทับฉบับเดิม'; el.classList.add('editing'); }
    else { el.textContent = 'ใบใหม่ ยังไม่ได้บันทึกลงประวัติ'; el.classList.remove('editing'); }
  }
  // ใบราคาส่งไม่รันเลขที่เอกสารอัตโนมัติ (ต่างจาก nextNo()/nextJobNo()) — เปิดใบใหม่แล้วปล่อยว่างให้กรอกเลขอ้างอิงเองถ้าต้องการ
  function newWholesale() {
    currentWholesaleId = null;
    applyWholesale({date: todayISO()});
    renderWholesaleEditState();
  }
  function renderWholesaleHistory() {
    const list = store.get('bs_wholesale', []).slice().sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
    const notice = cloudNotice() || (storageOK ? '' : '<p class="notice">เบราว์เซอร์นี้ไม่อนุญาตให้เก็บข้อมูลถาวร ประวัติจะอยู่จนกว่าจะปิดหน้านี้ ควรดาวน์โหลด PDF เก็บไว้ทุกครั้ง</p>');
    if (!list.length) { $('wholesaleHistory').innerHTML = notice + '<p class="empty">ยังไม่มีใบราคาส่งที่บันทึก กด “บันทึกลงประวัติ” เพื่อเก็บไว้เปิดแก้ไขภายหลัง</p>'; return; }
    const q = $('whHistSearch') ? $('whHistSearch').value : '';
    const shown = list.filter(w => matchesSearch(w.buyerName, q));
    if (!shown.length) { $('wholesaleHistory').innerHTML = notice + '<p class="empty">ไม่พบใบราคาส่งของลูกค้าชื่อ “' + esc(q) + '”</p>'; return; }
    $('wholesaleHistory').innerHTML = notice + '<ul>' + shown.map(w => {
      const t = wholesaleCalc(w);
      return '<li data-id="' + esc(w.id) + '"><div class="meta"><b>' + esc(w.buyerName || 'ไม่ระบุชื่อผู้ซื้อ') + '</b><small>' + esc(thDate(w.date)) + (w.ref ? ' · ' + esc(w.ref) : '') + (w.createdBy ? ' · โดย ' + esc(w.createdBy) : '') + '</small></div>' +
      '<span class="amt">' + money(t.total) + ' บาท</span>' +
      '<button class="status-pill ' + (w.paid ? 'billdone' : 'pending') + '" data-act="togglepaid" data-id="' + esc(w.id) + '" type="button" title="กดเพื่อสลับสถานะ">' + (w.paid ? 'ชำระแล้ว' : 'รอชำระ') + '</button>' +
      '<button class="btn small edit" data-act="open" type="button">เปิดแก้ไข</button>' +
      '<button class="btn small del" data-act="del" type="button">ลบ</button></li>';
    }).join('') + '</ul>';
  }
  function saveWholesale() {
    const list = store.get('bs_wholesale', []);
    const data = collectWholesale();
    if (!String(data.buyerName).trim()) { toast('ใส่ชื่อลูกค้า/ผู้ซื้อก่อนบันทึก'); $('whName').focus(); return; }
    const id = currentWholesaleId || ('w' + Date.now());
    const idx = list.findIndex(w => w.id === id);
    const createdBy = idx >= 0 ? list[idx].createdBy : (currentUser ? currentUser.name : '');
    const paid = idx >= 0 ? !!list[idx].paid : false;
    const rec = Object.assign({id, savedAt: Date.now(), createdBy, paid}, data);
    if (idx >= 0) list[idx] = rec; else list.push(rec);
    const wasEditing = idx >= 0;
    currentWholesaleId = rec.id;
    const persisted = store.set('bs_wholesale', list);
    cloudSave('wholesale', rec);
    upsertCustomer(rec.buyerName, '', '');
    renderWholesaleHistory(); renderWholesaleEditState();
    toast((persisted || cloudStatus === 'on') ? (wasEditing ? 'บันทึกทับใบราคาส่งแล้ว' : 'บันทึกใบราคาส่งแล้ว')
                    : 'บันทึกชั่วคราวแล้ว (เบราว์เซอร์เครื่องนี้ไม่อนุญาตให้เก็บถาวร และยังต่อคลาวด์ไม่ได้ — อย่าเพิ่งปิดหน้านี้)');
  }

  /* ---------------- พิมพ์ ---------------- */
  function doPrint(title) {
    const old = document.title;
    document.title = title;
    const restore = () => { document.title = old; window.removeEventListener('afterprint', restore); };
    window.addEventListener('afterprint', restore);
    const t0 = Date.now();
    try { window.print(); }
    catch (e) { restore(); toast('เปิดหน้าต่างพิมพ์ไม่ได้ ให้กด “ดาวน์โหลด PDF” แล้วพิมพ์จากไฟล์'); return; }
    // ถ้า print() กลับมาทันที และหน้านี้อยู่ในกรอบ แปลว่าอาจถูกบล็อก
    if (Date.now() - t0 < 300 && window.self !== window.top) {
      setTimeout(() => toast('ถ้าไม่มีหน้าต่างพิมพ์ขึ้น ให้กด “ดาวน์โหลด PDF” แล้วพิมพ์จากไฟล์'), 600);
    }
  }

  /* ---------------- สร้าง PDF เอง (ไม่พึ่งไลบรารีภายนอก) ---------------- */
  const S = 12, PW = 210, PH = 297, M = 12, CW = 186;      // S = พิกเซลต่อมิลลิเมตร (ยิ่งมากยิ่งคมเวลาพิมพ์)
  const INK = '#10233f', MUTED = '#4a5a72', LINE = '#c9d2de', LIGHT = '#e3e9f0', HEAD = '#eef2f7';
  const FB = "'Sarabun','Noto Sans Thai',system-ui,sans-serif", FH = "'Prompt','Sarabun','Noto Sans Thai',sans-serif";
  let logoEl = null, wmEl = null, sigEl = null;
  const loadImg = src => new Promise((res, rej) => { const im = new Image(); if (/^https?:/.test(src)) im.crossOrigin = 'anonymous'; im.onload = () => res(im); im.onerror = () => rej(new Error('โหลดภาพไม่ได้')); im.src = src; });

  async function prepAssets() {
    try {
      await Promise.race([
        Promise.all(['400', '600', '700'].map(w => document.fonts.load(w + ' 16px Sarabun', 'ทดสอบ กขค 0123')).concat(
          ['600', '700'].map(w => document.fonts.load(w + ' 16px Prompt', 'ทดสอบ กขค 0123')))),
        new Promise(r => setTimeout(r, 2500))]);
    } catch (e) { /* ใช้ฟอนต์สำรอง */ }
    if (!logoEl) logoEl = await loadImg(LOGO);
    if (!wmEl) { try { wmEl = await loadImg(WATERMARK); } catch (e) { wmEl = null; } }
    if (!sigEl) { try { sigEl = await loadImg(SIGNATURE); } catch (e) { sigEl = null; } }
  }
  // วาดโลโก้จางๆ กลางหน้ากระดาษ (ลายน้ำ) ไว้ด้านหลังเนื้อหาเอกสาร
  function drawWatermark(x) {
    if (!wmEl) return;
    const w = 150, h = w * wmEl.naturalHeight / wmEl.naturalWidth;
    x.save();
    x.globalAlpha = 0.12;
    x.drawImage(wmEl, (PW - w) / 2 * S, (PH - h) / 2 * S, w * S, h * S);
    x.restore();
  }
  function mkPage() {
    const c = document.createElement('canvas'); c.width = PW * S; c.height = PH * S;
    const x = c.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height);
    x.textBaseline = 'alphabetic';
    return {c, x};
  }
  const setF = (x, o) => { x.font = (o.w || 400) + ' ' + ((o.s || 3.7) * S) + 'px ' + (o.h ? FH : FB); };
  function T(x, str, px, py, o) {
    o = o || {}; setF(x, o); x.fillStyle = o.c || INK; x.textAlign = o.a || 'left';
    x.fillText(String(str), px * S, py * S);
  }
  const TW = (x, str, o) => { setF(x, o || {}); return x.measureText(String(str)).width / S; };
  const RECT = (x, x0, y0, w, h, fill) => { x.fillStyle = fill; x.fillRect(x0 * S, y0 * S, w * S, h * S); };
  function HL(x, x1, x2, y, color, wmm) { RECT(x, x1, y - (wmm || 0.2) / 2, x2 - x1, wmm || 0.2, color); }
  function rrPath(x, x0, y0, w, h, r) {
    x0 *= S; y0 *= S; w *= S; h *= S; r *= S;
    x.beginPath(); x.moveTo(x0 + r, y0); x.arcTo(x0 + w, y0, x0 + w, y0 + h, r); x.arcTo(x0 + w, y0 + h, x0, y0 + h, r);
    x.arcTo(x0, y0 + h, x0, y0, r); x.arcTo(x0, y0, x0 + w, y0, r); x.closePath();
  }
  const seg = (typeof Intl !== 'undefined' && Intl.Segmenter) ? new Intl.Segmenter('th', {granularity: 'word'}) : null;
  function wrapText(x, str, maxW, o) {
    const out = [];
    String(str).split('\n').forEach(par => {
      const toks = seg ? Array.from(seg.segment(par), s => s.segment) : Array.from(par);
      let line = '';
      toks.forEach(tk => {
        const test = line + tk;
        if (line && TW(x, test, o) > maxW) { out.push(line.replace(/\s+$/, '')); line = tk.replace(/^\s+/, ''); }
        else line = test;
      });
      out.push(line);
    });
    return out;
  }

  function drawHeader(x, title, rightLines, copy) {
    const lw = 26, lh = lw * logoEl.naturalHeight / logoEl.naturalWidth;
    x.drawImage(logoEl, M * S, M * S, lw * S, lh * S);
    const tx = M + lw + 4; let y = M + 4.6;
    T(x, shop.name, tx, y, {s: 5, w: 700, h: 1}); y += 5.4;
    const info = [shop.address,
      'เลขประจำตัวผู้เสียภาษี ' + shop.taxId + (String(shop.branch).trim() ? ' (' + shop.branch + ')' : ''),
      'โทร. ' + shop.phone];
    info.forEach(t => wrapText(x, t, 80, {s: 3.3}).forEach(l => { T(x, l, tx, y, {s: 3.3, c: MUTED}); y += 4.3; }));
    let ry = M + 4.6;
    T(x, title, PW - M, ry, {s: 4.9, w: 700, h: 1, a: 'right'}); ry += 3.4;
    if (copy) {
      const w = TW(x, copy, {s: 3.3, w: 700}) + 8;
      rrPath(x, PW - M - w, ry, w, 5.4, 2.7); x.strokeStyle = INK; x.lineWidth = 0.3 * S; x.stroke();
      T(x, copy, PW - M - w / 2, ry + 3.8, {s: 3.3, w: 700, a: 'center'}); ry += 8.6;
    } else ry += 2;
    rightLines.forEach(l => { T(x, l, PW - M, ry, {s: 3.5, c: MUTED, a: 'right'}); ry += 4.3; });
    const bottom = Math.max(M + lh, y - 1.5, ry - 2) + 2;
    HL(x, M, PW - M, bottom, INK, 0.55);
    return bottom + 6;
  }

  async function drawBillPages() {
    await prepAssets();
    const t = totals(), pages = [];
    let pg = mkPage(), x = pg.x; pages.push(pg.c); drawWatermark(x);
    let y = drawHeader(x, 'ใบเสร็จรับเงิน / ใบกำกับภาษี',
      ['เลขที่ ' + $('billNo').value, 'วันที่ ' + thDate($('billDate').value)], $('docCopy').value);
    // กล่องข้อมูลลูกค้า (กรอบพร้อมพื้นหลังอ่อนๆ และระยะขอบภายในให้ดูเป็นทางการมากขึ้น)
    const cPad = 5.5;
    // แสดงเฉพาะช่องที่กรอกจริง ช่องไหนว่างไม่ต้องขึ้น "—"
    const custRows = [];
    if ($('cName').value.trim()) custRows.push({t: $('cName').value.trim(), s: 4, w: 700, gap: 6.2});
    if ($('cPhone').value.trim()) custRows.push({t: $('cPhone').value.trim(), s: 3.6, w: 400, gap: 5.4});
    if ($('cAddr').value.trim()) wrapText(x, $('cAddr').value.trim(), CW - cPad * 2, {s: 3.6}).forEach(l => custRows.push({t: l, s: 3.6, w: 400, gap: 5.4}));
    if ($('cTax').value.trim()) custRows.push({t: 'เลขประจำตัวผู้เสียภาษี ' + $('cTax').value.trim(), s: 3.6, w: 400, gap: 5.4});
    const custLabelH = 7.2;
    const custBoxTop = y;
    const custLastGap = custRows.length ? custRows[custRows.length - 1].gap : 0;
    const custBoxH = cPad + custLabelH + custRows.reduce((a, r) => a + r.gap, 0) - custLastGap + 4.4 + cPad;
    RECT(x, M, custBoxTop, CW, custBoxH, '#f8fafc');
    x.strokeStyle = LINE; x.lineWidth = 0.3 * S; x.strokeRect(M * S, custBoxTop * S, CW * S, custBoxH * S);
    let cy = custBoxTop + cPad;
    T(x, 'ข้อมูลลูกค้า', M + cPad, cy + 2.6, {s: 3, w: 700, c: MUTED, h: 1}); cy += custLabelH;
    custRows.forEach(r => { T(x, r.t, M + cPad, cy + 3, {s: r.s, w: r.w}); cy += r.gap; });
    y = custBoxTop + custBoxH + 9;
    // ตาราง
    const c0 = M, c1 = M + 14, c2 = c1 + 92, c3 = c2 + 22, c4 = c3 + 28, cR = M + CW;
    const head = () => {
      RECT(x, M, y, CW, 8.4, HEAD); HL(x, M, cR, y, LINE, 0.25); HL(x, M, cR, y + 8.4, LINE, 0.25);
      const b = y + 5.7, o = {s: 3.5, w: 700};
      T(x, 'ลำดับ', c0 + 7, b, Object.assign({a: 'center'}, o)); T(x, 'รายการ', c1 + 3, b, o);
      T(x, 'จำนวน', c3 - 3, b, Object.assign({a: 'right'}, o)); T(x, 'ราคา/ชิ้น', c4 - 3, b, Object.assign({a: 'right'}, o));
      T(x, 'รวม', cR - 3, b, Object.assign({a: 'right'}, o));
      y += 8.4;
    };
    head();
    const shown = items.filter(i => i.name.trim() || num(i.qty) * num(i.price) > 0);
    const rows = shown.length ? shown : [{name: 'ยังไม่มีรายการ', qty: '', price: '', empty: true}];
    rows.forEach((it, n) => {
      const lines = wrapText(x, it.name, 92 - 6, {s: 3.7});
      const rh = 6.2 + Math.max(1, lines.length) * 4.8;
      if (y + rh > PH - M - 6) { pg = mkPage(); x = pg.x; pages.push(pg.c); drawWatermark(x); y = M; head(); }
      const b = y + 3 + 3.6;
      if (!it.empty) T(x, n + 1, c0 + 7, b, {s: 3.7, a: 'center'});
      lines.forEach((l, k) => T(x, l, c1 + 3, b + k * 4.8, {s: 3.7, c: it.empty ? MUTED : INK}));
      if (!it.empty) {
        T(x, fmt(num(it.qty)), c3 - 3, b, {s: 3.7, a: 'right'});
        T(x, money(num(it.price) / t.vd), c4 - 3, b, {s: 3.7, a: 'right'});
        T(x, money(num(it.qty) * num(it.price) / t.vd), cR - 3, b, {s: 3.7, a: 'right'});
      }
      y += rh; HL(x, M, cR, y, LIGHT, 0.2);
    });
    // ยอดรวม (ตัดแถว "รวมรายการ" และ "ราคาก่อน VAT" ออก เหลือเฉพาะส่วนลด/VAT/รวมทั้งสิ้น)
    const tot = [['ส่วนลด', t.disc / t.vd]];
    if (t.mode !== 'none') tot.push(['ภาษีมูลค่าเพิ่ม (VAT) ' + fmt(t.rate) + '%', t.vat]);
    const noteLines = $('note').value.trim() ? wrapText(x, $('note').value.trim(), CW - 18, {s: 3.6}) : [];
    const need = 9 + tot.length * 6.6 + 13 + 13 + (noteLines.length ? noteLines.length * 4.8 + 7 : 0) + 36;
    if (y + need > PH - M) { pg = mkPage(); x = pg.x; pages.push(pg.c); drawWatermark(x); y = M; }
    y += 9;
    const bx = PW - M - 86;
    tot.forEach(r => {
      T(x, r[0], bx, y + 3.8, {s: 3.7, c: MUTED}); T(x, money(r[1]), PW - M, y + 3.8, {s: 3.7, a: 'right'}); y += 6.6;
    });
    HL(x, bx, PW - M, y + 0.8, INK, 0.4); y += 2.6;
    // จำนวนเงินตัวอักษร (ซ้าย) อยู่แถวเดียวกับกล่องรวมทั้งสิ้น (ขวา)
    RECT(x, M, y - 1.5, bx - 6 - M, 11.5, HEAD);
    T(x, bahtText(t.total), M + 4, y + 6.4, {s: 3.8, w: 700});
    RECT(x, bx - 3, y - 1.5, (PW - M) - (bx - 3) + 3, 11.5, HEAD);
    T(x, 'รวมทั้งสิ้น', bx, y + 6.4, {s: 4.4, w: 700, h: 1}); T(x, money(t.total), PW - M, y + 6.4, {s: 4.6, w: 700, h: 1, a: 'right'}); y += 10.5;
    if (t.dep > 0) { T(x, 'รับมัดจำแล้ว', bx, y + 3.8, {s: 3.7, c: MUTED}); T(x, money(t.dep), PW - M, y + 3.8, {s: 3.7, a: 'right'}); y += 6.6; }
    y += 5.5;
    HL(x, M, PW - M, y, LINE, 0.2); y += 6.5;
    if (noteLines.length) {
      T(x, 'หมายเหตุ', M, y + 3.6, {s: 3.6, w: 700});
      noteLines.forEach((l, k) => T(x, l, M + 18, y + 3.6 + k * 4.8, {s: 3.6}));
    }
    // ลายเซ็น (ท้ายหน้า) — เส้นเซ็นด้านบน ตามด้วยคำอธิบายและช่องวันที่ ให้ดูเป็นทางการ
    // ฝั่งผู้รับเงิน (ร้าน) ประทับลายเซ็นและวันที่ให้อัตโนมัติ ส่วนฝั่งผู้จ่ายเงินเว้นว่างให้เซ็นเอง
    const sigLineY = PH - M - 21, colW = 74;
    if (sigEl) {
      const sw = 50, sh = sw * sigEl.naturalHeight / sigEl.naturalWidth;
      x.drawImage(sigEl, (M + colW / 2 - sw / 2 - 2) * S, (sigLineY - sh + 5) * S, sw * S, sh * S);
    }
    [[M + colW / 2, 'ผู้รับเงิน', thDate($('billDate').value)], [PW - M - colW / 2, 'ผู้จ่ายเงิน', '....../....../......']].forEach(([cx, label, dateTxt]) => {
      HL(x, cx - 27, cx + 27, sigLineY, INK, 0.25);
      T(x, label, cx, sigLineY + 5.6, {s: 3.7, a: 'center'});
      T(x, 'วันที่ ' + dateTxt, cx, sigLineY + 11.6, {s: 3.3, c: MUTED, a: 'center'});
    });
    return pages;
  }

  async function drawCalcPages() {
    await prepAssets();
    const r = lastLayout || readLayout();
    const sel = $('paper'), paperName = sel.options[sel.selectedIndex].text;
    const pg = mkPage(), x = pg.x;
    let y = drawHeader(x, 'ผลคำนวณการเรียงสติ๊กเกอร์', ['วันที่ ' + thDate(todayISO())], null);
    const kv = [
      ['กระดาษ', paperName], ['ขนาดสติ๊กเกอร์', fmt(r.sw) + ' × ' + fmt(r.sh) + ' ซม.'],
      ['ช่องไฟ / ขอบแต่ละด้าน', fmt(r.gap) + ' / ' + fmt(r.m) + ' ซม.'],
      ['จำนวนที่เรียงได้ต่อแผ่น', r.count.toLocaleString('en-US') + ' ชิ้น', true],
      ['การเรียง', r.cols + ' ชิ้นต่อแถว × ' + r.rows + ' แถว'],
      ['พื้นที่ใช้เรียง', r.count ? fmt(r.usedW) + ' × ' + fmt(r.usedH) + ' ซม.' : '—'],
      ['เหลือ กว้าง / ยาว', r.count ? fmt(r.leftW) + ' / ' + fmt(r.leftH) + ' ซม.' : '—']];
    kv.forEach(row => {
      const h = row[2] ? 11 : 7.4;
      T(x, row[0], M + 2, y + h / 2 + 1.3, {s: 3.8, c: MUTED});
      if (row[2]) T(x, row[1], M + CW * 0.38 + 2, y + h / 2 + 2.2, {s: 6, w: 700, h: 1});
      else T(x, row[1], M + CW * 0.38 + 2, y + h / 2 + 1.4, {s: 3.9, w: 600});
      y += h; HL(x, M, M + CW, y, LIGHT, 0.2);
    });
    y += 6;
    const big = Math.max(r.pw, r.ph), pad = big * 0.075;
    const availW = CW, availH = PH - M - 10 - y;
    const sc = Math.min(availW / (r.pw + pad * 2), availH / (r.ph + pad * 2));
    const ox = M + (availW - (r.pw + pad * 2) * sc) / 2 + pad * sc, oy = y + pad * sc;
    RECT(x, ox, oy, r.pw * sc, r.ph * sc, '#ffffff');
    if (r.count > 0) {
      x.beginPath();
      for (let a = 0; a < r.rows; a++) for (let b = 0; b < r.cols; b++) {
        x.rect((ox + (r.m + b * (r.sw + r.gap)) * sc) * S, (oy + (r.m + a * (r.sh + r.gap)) * sc) * S, r.sw * sc * S, r.sh * sc * S);
      }
      x.fillStyle = '#7fd3ef'; x.fill();
      const lw = Math.min(0.25, r.sw * sc * 0.06, r.sh * sc * 0.06);
      if (lw >= 0.04) { x.strokeStyle = '#0d6f92'; x.lineWidth = lw * S; x.stroke(); }
    }
    if (r.m > 0) {
      x.save(); x.setLineDash([1.2 * S, 0.8 * S]); x.strokeStyle = '#d81f66'; x.lineWidth = 0.25 * S;
      x.strokeRect((ox + r.m * sc) * S, (oy + r.m * sc) * S, r.aw * sc * S, r.ah * sc * S); x.restore();
    }
    x.strokeStyle = INK; x.lineWidth = 0.35 * S; x.strokeRect(ox * S, oy * S, r.pw * sc * S, r.ph * sc * S);
    T(x, 'กว้าง ' + fmt(r.pw) + ' ซม.', ox + r.pw * sc / 2, oy - 2, {s: 3.3, w: 600, c: MUTED, a: 'center'});
    x.save(); x.translate((ox - 2.2) * S, (oy + r.ph * sc / 2) * S); x.rotate(-Math.PI / 2);
    T(x, 'ยาว ' + fmt(r.ph) + ' ซม.', 0, 0, {s: 3.3, w: 600, c: MUTED, a: 'center'}); x.restore();
    T(x, 'คำนวณแบบตารางตามแนวที่กำหนด ไม่สลับแนวหรือเรียงสลับฟันปลา ภาพตัวอย่างไม่ใช่ไฟล์สำหรับพิมพ์', M, PH - M - 1, {s: 3.1, c: MUTED});
    return [pg.c];
  }

