    const rows = shown.length ? shown : [{name: 'ยังไม่มีรายการ', qty: '', note: '', empty: true}];
    rows.forEach((it, n) => {
      const nameLines = wrapText(x, it.name, cQ - c1 - 6, {s: 3.7});
      const noteLines = (!it.empty && it.note && it.note.trim()) ? wrapText(x, it.note, cQ - c1 - 6, {s: 3.3}) : [];
      const rh = 4.8 + Math.max(1, nameLines.length) * 4.6 + noteLines.length * 4.1;
      if (y + rh > PH - M - 6) { pg = mkPage(); x = pg.x; pages.push(pg.c); y = M; head(); }
      const b = y + 2.4 + 3.4;
      if (!it.empty) T(x, n + 1, c0 + 7, b, {s: 3.7, a: 'center'});
      nameLines.forEach((l, k) => T(x, l, c1 + 2, b + k * 4.6, {s: 3.7, c: it.empty ? MUTED : INK}));
      let ny = b + nameLines.length * 4.6;
      noteLines.forEach((l, k) => { T(x, l, c1 + 2, ny + k * 4.1, {s: 3.3, c: MUTED}); });
      if (!it.empty) T(x, fmt(num(it.qty)), cR - 2, b, {s: 3.7, a: 'right'});
      y += rh; HL(x, M, cR, y, LIGHT, 0.2);
    });
    y += 6;
    const noteLines = $('jobNote').value.trim() ? wrapText(x, $('jobNote').value.trim(), CW - 18, {s: 3.6}) : [];
    if (noteLines.length) {
      const need = 6 + noteLines.length * 4.6 + 22;
      if (y + need > PH - M) { pg = mkPage(); x = pg.x; pages.push(pg.c); y = M; }
      T(x, 'ข้อกำหนดการผลิต / หมายเหตุ', M, y + 3.6, {s: 3.6, w: 700}); y += 4.6;
      noteLines.forEach(l => { T(x, l, M, y + 3.6, {s: 3.6}); y += 4.6; });
    }
    // รูปอ้างอิงงาน (ถ้ามี)
    if (jobPhotos.length) {
      y += 2.4;
      if (y + 12 > PH - M - 30) { pg = mkPage(); x = pg.x; pages.push(pg.c); y = M; }
      T(x, 'รูปอ้างอิงงาน', M, y + 3.6, {s: 3.6, w: 700}); y += 8;
      const gl = photoGridLayout(jobPhotos.length);
      const TS = gl.size, GAP = gl.gap, cols = gl.cols;
      const rowW = cols * TS + (cols - 1) * GAP, startX = M + (CW - rowW) / 2;
      const imgs = await Promise.all(jobPhotos.map(src => loadImg(src).catch(() => null)));
      let col = 0;
      imgs.forEach(im => {
        if (!im) return;
        if (col === 0 && y + TS + 4 > PH - M - 30) { pg = mkPage(); x = pg.x; pages.push(pg.c); y = M; }
        const px = startX + col * (TS + GAP), py = y;
        const iw = im.naturalWidth || im.width, ih = im.naturalHeight || im.height, side = Math.min(iw, ih);
        const sx = (iw - side) / 2, sy2 = (ih - side) / 2;
        x.save();
        rrPath(x, px, py, TS, TS, 2.5);
        x.clip();
        x.drawImage(im, sx, sy2, side, side, px * S, py * S, TS * S, TS * S);
        x.restore();
        rrPath(x, px, py, TS, TS, 2.5);
        x.strokeStyle = LINE; x.lineWidth = 0.3 * S; x.stroke();
        col++;
        if (col >= cols) { col = 0; y += TS + GAP; }
      });
      if (col !== 0) y += TS + GAP;
    }
    // ลายเซ็น (ท้ายหน้า)
