  function thDateShort(iso) {
    try {
      const d = new Date(iso + 'T00:00:00');
      const dd = String(d.getDate()).padStart(2, '0'), mm = String(d.getMonth() + 1).padStart(2, '0');
      const yy = String((d.getFullYear() + 543) % 100).padStart(2, '0');
      return dd + '/' + mm + '/' + yy;
    } catch (e) { return iso || '—'; }
  }

