  function b64ToBytes(dataUrl) {
    const bin = atob(dataUrl.split(',')[1]), u = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    return u;
  }
  // แปลงหน้า canvas เป็นพิกเซล RGB ดิบแล้วบีบอัดแบบไม่สูญเสียคุณภาพ (Flate/zlib) สำหรับฝังใน PDF โดยตรง
  // คมกว่าการเข้ารหัส JPEG (ซึ่งมีการสูญเสียคุณภาพรอบตัวอักษรและเส้นบางๆ ทำให้เวลาพิมพ์ออกมาไม่คมเท่าที่ควร)
  // ถ้าเบราว์เซอร์ไม่รองรับ CompressionStream จะคืนค่า null ให้ใช้ JPEG คุณภาพสูงแทนโดยอัตโนมัติ
  async function canvasToFlateRGB(c) {
    if (typeof CompressionStream === 'undefined') return null;
    try {
      const ctx = c.getContext('2d');
      const {width: w, height: h} = c;
      const src = ctx.getImageData(0, 0, w, h).data;
      const rgb = new Uint8Array(w * h * 3);
      for (let i = 0, j = 0; i < src.length; i += 4, j += 3) { rgb[j] = src[i]; rgb[j + 1] = src[i + 1]; rgb[j + 2] = src[i + 2]; }
      const cs = new CompressionStream('deflate');
      const writer = cs.writable.getWriter();
      writer.write(rgb); writer.close();
      const buf = await new Response(cs.readable).arrayBuffer();
      return {data: new Uint8Array(buf), w, h};
    } catch (e) { console.error('flate encode failed', e); return null; }
  }
  async function pageToPdfImage(c) {
    const flate = await canvasToFlateRGB(c);
    if (flate) return {data: flate.data, w: flate.w, h: flate.h, filter: 'FlateDecode'};
    return {data: b64ToBytes(c.toDataURL('image/jpeg', 0.95)), w: c.width, h: c.height, filter: 'DCTDecode'};
  }
  function buildPdf(imgs) {
    const enc = new TextEncoder(), parts = [], off = []; let pos = 0;
    const add = d => { const b = typeof d === 'string' ? enc.encode(d) : d; parts.push(b); pos += b.length; };
    const obj = (id, body) => { off[id] = pos; add(id + ' 0 obj\n' + body + '\nendobj\n'); };
    add('%PDF-1.4\n'); add(new Uint8Array([0x25, 0xE2, 0xE3, 0xCF, 0xD3, 0x0A]));
    obj(1, '<< /Type /Catalog /Pages 2 0 R >>');
    obj(2, '<< /Type /Pages /Kids [' + imgs.map((_, i) => (3 + i * 3) + ' 0 R').join(' ') + '] /Count ' + imgs.length + ' >>');
    imgs.forEach((im, i) => {
      const pid = 3 + i * 3, cid = pid + 1, iid = pid + 2, cs = 'q 595.28 0 0 841.89 0 0 cm /Im0 Do Q';
      obj(pid, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ' + iid + ' 0 R >> /ProcSet [/PDF /ImageC] >> /Contents ' + cid + ' 0 R >>');
      obj(cid, '<< /Length ' + cs.length + ' >>\nstream\n' + cs + '\nendstream');
      off[iid] = pos;
      add(iid + ' 0 obj\n<< /Type /XObject /Subtype /Image /Width ' + im.w + ' /Height ' + im.h +
        ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /' + (im.filter || 'DCTDecode') + ' /Length ' + im.data.length + ' >>\nstream\n');
      add(im.data); add('\nendstream\nendobj\n');
    });
    const total = 3 + imgs.length * 3, xref = pos;
    let xs = 'xref\n0 ' + total + '\n0000000000 65535 f \n';
    for (let i = 1; i < total; i++) xs += String(off[i]).padStart(10, '0') + ' 00000 n \n';
    add(xs + 'trailer\n<< /Size ' + total + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF');
    return new Blob(parts, {type: 'application/pdf'});
  }

  async function saveBlob(blob, filename) {
    let dl = null;
    try { dl = window.claude && window.claude.use ? await window.claude.use('downloads') : null; } catch (e) { dl = null; }
    if (dl) {
      try { await dl.save({filename, data: blob}); return 'saved'; }
      catch (e) { if (e && e.code === 'declined') return 'declined'; }
    }
    try {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob); a.download = filename;
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 8000);
      return 'anchor';
    } catch (e) { return 'failed'; }
  }

