  /* พิมพ์/ดาวน์โหลดใบกำกับภาษีที่ติ๊กเลือกไว้ในประวัติเอกสาร รวมเป็นไฟล์เดียว (เรียงตามวันที่จากน้อยไปมาก)
     ใช้รายการที่ติ๊กเลือกจริง (ไม่ใช่กรองด้วยข้อความเดือนอย่างเดียว) เพื่อกันปัญหาข้อมูลเก่าที่วันที่
     ในระบบไม่ตรงรูปแบบเดือนที่เลือก — ทำโดยโหลดข้อมูลแต่ละใบเข้าฟอร์ม (เหมือนกด "เปิดแก้ไข") ทีละใบ
     วาดหน้าเอกสารเก็บไว้ แล้วคืนค่าฟอร์มกลับเป็นของเดิมหลังทำเสร็จ ไม่กระทบเอกสารที่กำลังเปิดอยู่ */
  async function exportAllBills(btn, opts) {
    const forPrint = !!(opts && opts.forPrint);
    const all = store.get('bs_bills', []);
    const list = all.filter(b => histSelected.has(b.id))
      .slice().sort((a, b) => String(a.date).localeCompare(String(b.date)) || String(a.no).localeCompare(String(b.no)));
    if (!list.length) { toast('กรุณาติ๊กเลือกเอกสารที่ต้องการก่อน (เลือกเดือนด้านบนเพื่อติ๊กทั้งเดือน หรือติ๊กเลือกเป็นรายใบ)'); return; }
    lastWasPrint = forPrint;
    const html = btn.innerHTML;
    btn.disabled = true;
    let win = null;
    if (forPrint) { try { win = window.open('', '_blank'); } catch (e) { win = null; } }
    const savedId = currentId, savedForm = collect();
    try {
      let allPages = [];
      // ถ้าเลือก "พิมพ์เป็นชุด" ไว้ (ต้นฉบับ/สำเนา) ให้บังคับใช้ป้ายนี้กับทุกใบที่พิมพ์รวมกัน
      // โดยไม่แก้ค่าที่บันทึกไว้จริงของแต่ละใบ (คืนค่าฟอร์มกลับเป็นของเดิมหลังทำเสร็จเหมือนเดิม)
      const copyOverride = $('histPrintCopy') ? $('histPrintCopy').value : '';
      for (let i = 0; i < list.length; i++) {
        btn.textContent = 'กำลังเตรียม ' + (i + 1) + '/' + list.length + '…';
        apply(list[i]);
        if (copyOverride) $('docCopy').value = copyOverride;
        const pages = await drawBillPages();
        allPages = allPages.concat(pages);
      }
      const imgs = await Promise.all(allPages.map(pageToPdfImage));
      const blob = buildPdf(imgs);
      const monthSel = $('histPrintMonth') ? $('histPrintMonth').value : '';
      const name = ('ใบกำกับภาษีที่เลือก-' + (monthSel || 'รวม') + (copyOverride ? '-' + copyOverride : '') + '-' + list.length + 'ใบ.pdf').replace(/[\\/:*?"<>|]/g, '-');
      lastPdf = {blob, name};
      if (pdfUrl) URL.revokeObjectURL(pdfUrl);
      pdfUrl = URL.createObjectURL(blob);
      showOverlay(name, allPages, pdfUrl, forPrint ? 'กำลังบันทึกไฟล์สำหรับพิมพ์…' : 'กำลังบันทึกไฟล์…', forPrint);
      if (win && !win.closed) { try { win.location.href = pdfUrl; } catch (e) {} }
      const res = await saveBlob(blob, name);
      $('ovStatus').textContent = forPrint ? (SAVE_MSG_PRINT[res] || SAVE_MSG_PRINT.failed) : (SAVE_MSG[res] || SAVE_MSG.failed);
    } catch (e) {
      console.error(e);
      if (win && !win.closed) { try { win.close(); } catch (er) {} }
      toast('สร้างไฟล์ PDF ไม่สำเร็จ: ' + ((e && e.message) || 'ไม่ทราบสาเหตุ'));
    } finally {
      currentId = savedId; apply(savedForm); renderEditState();
      btn.disabled = false; btn.innerHTML = html;
    }
  }
  const inFrame = () => { try { return window.self !== window.top; } catch (e) { return true; } };
