  function openFromLink(href) {
    try {
      const u = new URL(href, location.href), tab = u.searchParams.get('tab'), chat = u.searchParams.get('chat');
      if (tab && can(tab)) showTab(tab);
      if (tab === 'chat' && chat && typeof openChat === 'function') setTimeout(() => openChat(chat), 300);
    } catch (e) {}
  }
