    const fail = m => { err.textContent = m; err.hidden = false; };
    const amount = Math.round(num(String($('bkAmt').value).replace(/[,\s]/g, '')) * 100) / 100;
    if (!(amount > 0)) return fail('ใส่จำนวนเงินให้ถูกต้อง');
    const when = $('bkWhen').value ? new Date($('bkWhen').value).getTime() : Date.now();
    if (!isFinite(when)) return fail('ใส่วันที่และเวลาให้ถูกต้อง');
    if (when > Date.now() + 60000) return fail('วันเวลาต้องไม่เกินตอนนี้');
    const balTxt = String($('bkBal').value).replace(/[,\s]/g, '');
    const balance = balTxt === '' ? null : num(balTxt);
    if (balTxt !== '' && !(balance >= 0)) return fail('ยอดคงเหลือไม่ถูกต้อง');
    const dir = bkDir(), account = $('bkAcc').value, party = $('bkParty').value.trim().slice(0, 40), note = $('bkNote').value.trim().slice(0, 80);
    const d = new Date(when);
    const smsTime = pad2(d.getDate()) + '/' + pad2(d.getMonth() + 1) + '/' + String(d.getFullYear() + 543).slice(-2) + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
    const id = (dir === 'in' ? 'bim' : 'bom') + Date.now() + Math.random().toString(36).slice(2, 6);
    const base = {id, account, amount, smsTime, note, source: 'manual', addedBy: currentUser ? (currentUser.name || currentUser.username) : '', createdAt: when};
    const rec = dir === 'in' ? Object.assign(base, {from: party}) : Object.assign(base, {kind: 'เงินออก', to: party});
    const key = dir === 'in' ? 'bs_bank_in' : 'bs_bank_out';
    if (dir === 'in') { // เครื่องนี้ไม่ต้องเด้งแจ้งเตือนรายการที่เพิ่มเอง
      try { const seen = +localStorage.getItem(BANKIN_SEEN) || 0; if (when > seen) localStorage.setItem(BANKIN_SEEN, String(when)); } catch (e2) {}
    }
