  (function initAiSettings() {
    const providerSel = $('aiProvider'), keyInput = $('aiApiKey'), modelInput = $('aiModel');
    const keyWrap = $('aiKeyWrap'), modelWrap = $('aiModelWrap'), hint = $('aiHint'), toggleBtn = $('aiKeyToggle');
    const modelPlaceholder = { openai: 'gpt-4o-mini', gemini: 'gemini-1.5-flash' };
    function syncVisibility() {
      const on = providerSel.value !== 'none';
      keyWrap.hidden = !on; modelWrap.hidden = !on; hint.hidden = !on;
      modelInput.placeholder = modelPlaceholder[providerSel.value] || '';
    }
    providerSel.value = localStorage.getItem('bs_ai_provider') || 'none';
    keyInput.value = localStorage.getItem('bs_ai_key') || '';
    modelInput.value = localStorage.getItem('bs_ai_model') || '';
    syncVisibility();
    providerSel.addEventListener('change', syncVisibility);
    toggleBtn.addEventListener('click', () => {
      const show = keyInput.type === 'password';
      keyInput.type = show ? 'text' : 'password';
      toggleBtn.textContent = show ? 'ซ่อน' : 'แสดง';
    });
    $('aiSettingsSave').addEventListener('click', () => {
      localStorage.setItem('bs_ai_provider', providerSel.value);
      localStorage.setItem('bs_ai_key', keyInput.value.trim());
      localStorage.setItem('bs_ai_model', modelInput.value.trim());
      updateOcrButtonLabel();
      toast('บันทึกการตั้งค่า AI แล้ว');
    });
  })();
